// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        assertTrue(address(c).balance == amount);
        vm.prank(actor);
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}
